const expected = String($env.N8N_PROXY_SECRET || '');
const supplied = String(($json.headers || {})['x-n8n-proxy-secret'] || '');
return [{ json: { ...$json, proxy_authorized: Boolean(expected && supplied === expected) } }];

const users = $('Read Users').all().map(i => i.json).filter(x => x.user_id);
const prescriptions = $('Read Prescriptions').all().map(i => i.json).filter(x => x.prescription_id && x.user_id);
const allNudges = $('Read Nudges').all().map(i => i.json).filter(n => n.nudge_id && n.user_id);
const sourceNudges = allNudges.filter(n =>
  !String(n.nudge_id).startsWith('schd_') &&
  ['needs_review', 'pending', 'approved', 'rejected'].includes(String(n.status || 'needs_review'))
);
const scheduleNudges = allNudges.filter(n =>
  String(n.nudge_id).startsWith('schd_') &&
  ['approved', 'sent'].includes(String(n.status || ''))
);
const numberFields = ['frequency_per_week', 'duration_weeks', 'week_number'];
for (const row of [...prescriptions, ...sourceNudges, ...scheduleNudges]) {
  for (const key of numberFields) if (row[key] !== '' && row[key] != null && !Number.isNaN(Number(row[key]))) row[key] = Number(row[key]);
}
const patients = users.map(u => {
  const nudges = sourceNudges.filter(n => n.user_id === u.user_id);
  const schedule_nudges = scheduleNudges.filter(n => n.user_id === u.user_id);
  const statuses = nudges.map(n => String(n.status || 'needs_review'));
  const status = statuses.some(s => s === 'needs_review' || s === 'pending') ? 'needs_review'
    : statuses.some(s => s === 'approved') ? 'approved'
    : statuses.some(s => s === 'rejected') ? 'rejected'
    : 'no_review_items';
  return {
    user_id: u.user_id, name: u.name || '', phone: u.phone || '', email: u.email || '',
    user_status: u.user_status || '', status,
    prescriptions: prescriptions.filter(p => p.user_id === u.user_id), nudges, schedule_nudges
  };
}).sort((a, b) => String(a.name).localeCompare(String(b.name)));
return [{ json: { patients, count: patients.length, generated_at: new Date().toISOString() } }];

const payload = $json;
const rows = $('Read Weekly Schedule').all().map(i => i.json).filter(r => r.schedule_slot_id && r.user_id);
for (const patient of payload.patients || []) patient.weekly_schedule = rows.filter(r => String(r.user_id) === String(patient.user_id));
return [{ json: payload }];

const payload = $json;
const users = $('Read Users').all().map(i => i.json);
for (const patient of payload.patients || []) {
  const user = users.find(u => String(u.user_id) === String(patient.user_id)) || {};
  const legacy = [...new Set((patient.prescriptions || []).map(p => String(p.doctor_id || '')).filter(Boolean))];
  patient.doctor_id = String(user.doctor_id || (legacy.length === 1 ? legacy[0] : ''));
  patient.ownership_needs_review = !user.doctor_id && legacy.length !== 1;
}
return [{ json: payload }];

const expected = String($env.N8N_PROXY_SECRET || '');
const supplied = String(($json.headers || {})['x-n8n-proxy-secret'] || '');
return [{ json: { ...$json, proxy_authorized: Boolean(expected && supplied === expected) } }];

const body = $('Webhook Approve').first().json.body || {};
const decision = body.decision === 'reject' ? 'rejected' : body.decision === 'approve' ? 'approved' : '';
const userId = String(body.user_id || '').trim();
const slots = Array.isArray(body.slots) ? body.slots : [];
const days = ['sunday','monday','tuesday','wednesday','thursday','friday','saturday'];
const daySet = new Set(days);
const pillars = new Set(['nutrition','physical_activity','sleep','stress_management','substance_use','social_connection']);
const types = new Set(['reminder','reflection','challenge','affirmation']);
const tones = new Set(['encouraging','neutral_informational','custom']);
const templates = new Set(['health_plan_reminder','hello_world']);
const dateRe = /^\d{4}-\d{2}-\d{2}$/;
const timeRe = /^([01]\d|2[0-3]):[0-5]\d$/;
if (!userId) throw new Error('user_id is required');
if (!decision) throw new Error('decision must be approve or reject');
if (!slots.length) throw new Error('at least one weekly slot is required');
for (const [i, s] of slots.entries()) {
  if (!daySet.has(String(s.day))) throw new Error(`slots[${i}].day is invalid`);
  if (!timeRe.test(String(s.time || ''))) throw new Error(`slots[${i}].time is invalid`);
  if (!types.has(String(s.nudge_type))) throw new Error(`slots[${i}].nudge_type is invalid`);
  if (!pillars.has(String(s.pillar))) throw new Error(`slots[${i}].pillar is invalid`);
  if (!tones.has(String(s.tone_variant))) throw new Error(`slots[${i}].tone_variant is invalid`);
  if (!templates.has(String(s.template_name || 'health_plan_reminder'))) throw new Error(`slots[${i}].template_name is invalid`);
  if (!String(s.prescription_id || '').trim()) throw new Error(`slots[${i}].prescription_id is required`);
  if (!String(s.source_nudge_id || '').trim()) throw new Error(`slots[${i}].source_nudge_id is required`);
  if (!String(s.message_body || '').trim() || String(s.message_body).length > 1024) throw new Error(`slots[${i}].message_body is invalid`);
}
const now = new Date().toISOString();
const sourceIds = [...new Set(slots.map(s => String(s.source_nudge_id).trim()))];
const source_updates = sourceIds.map(nudge_id => ({ nudge_id, status: decision, reviewed_at: now }));
const dated_nudges = [];
const schedule_rows = [];
if (decision === 'approved') {
  const start = String(body.start_date || '');
  const end = String(body.end_date || '');
  if (!dateRe.test(start) || !dateRe.test(end)) throw new Error('start_date and end_date must be YYYY-MM-DD');
  const startMs = Date.parse(start + 'T00:00:00Z');
  const endMs = Date.parse(end + 'T00:00:00Z');
  if (!Number.isFinite(startMs) || !Number.isFinite(endMs) || endMs < startMs) throw new Error('invalid approval date range');
  const dayCount = Math.floor((endMs - startMs) / 86400000) + 1;
  if (dayCount > 366) throw new Error('approval range cannot exceed 366 days');
  for (let offset = 0; offset < dayCount; offset++) {
    const date = new Date(startMs + offset * 86400000);
    const iso = date.toISOString().slice(0, 10);
    const weekday = days[date.getUTCDay()];
    slots.forEach((s, slotIndex) => {
      if (String(s.day) !== weekday) return;
      const source = String(s.source_nudge_id).replace(/[^A-Za-z0-9_-]/g, '').slice(-48) || 'source';
      const nudge_id = `schd_${source}_${iso.replace(/-/g, '')}_${String(s.time).replace(':', '')}_${slotIndex}`;
      const tone = s.tone_variant === 'custom' ? 'neutral_informational' : s.tone_variant;
      const nudge = {
        nudge_id, prescription_id: String(s.prescription_id), user_id: userId,
        nudge_type: String(s.nudge_type), pillar: String(s.pillar),
        scheduled_date: iso, scheduled_time: String(s.time),
        message_body: String(s.message_body).trim(), message_body_alt: String(s.message_body_alt || ''),
        tone_variant: tone, template_name: String(s.template_name || 'health_plan_reminder'),
        status: 'approved', sent_at: '', reviewed_at: now, week_number: Math.floor(offset / 7) + 1
      };
      dated_nudges.push(nudge);
      schedule_rows.push({
        schedule_id: `sch_${nudge_id}`, nudge_id, user_id: userId, status: 'approved', sent_at: '',
        wa_message_id: '', barrier_followup_wa_id: '', tone_sent: '', response: '', responded_at: '',
        last_response_at: '', barrier_tag: '', done_count: 0, skip_count: 0, current_streak: 0,
        consecutive_skips: 0, last_updated: now
      });
    });
  }
  if (!dated_nudges.length) throw new Error('weekly slots produced no dated nudges in the selected range');
  if (dated_nudges.length > 2000) throw new Error('approval would create more than 2000 dated nudges');
}
return [{ json: { decision, user_id: userId, dated_nudges, schedule_rows, source_updates,
  summary: { status: 'ok', decision, user_id: userId, count: dated_nudges.length, source_count: source_updates.length } } }];

const plan = $json;
if (plan.decision !== 'approved') return [{ json: plan }];
const body = $('Webhook Approve').first().json.body || {};
const slots = Array.isArray(body.slots) ? body.slots : [];
const existing = $('Read Existing Weekly Schedule').all().map(i => i.json).filter(r => r.schedule_slot_id && String(r.user_id) === String(plan.user_id));
const existingById = new Map(existing.map(r => [String(r.schedule_slot_id), r]));
const now = new Date().toISOString();
const token = value => String(value || '').replace(/[^A-Za-z0-9_-]/g, '').slice(-60);
const used = new Set();
const active = slots.map((slot, index) => {
  const fallback = `slot_${token(slot.source_nudge_id) || 'source'}_${token(slot.day)}_${index}`;
  const schedule_slot_id = token(slot.schedule_slot_id) || fallback;
  if (used.has(schedule_slot_id)) throw new Error(`duplicate schedule_slot_id: ${schedule_slot_id}`);
  used.add(schedule_slot_id);
  const prior = existingById.get(schedule_slot_id) || {};
  return {
    schedule_slot_id, user_id: plan.user_id, source_nudge_id: String(slot.source_nudge_id), prescription_id: String(slot.prescription_id),
    day: String(slot.day), scheduled_time: String(slot.time), nudge_type: String(slot.nudge_type), pillar: String(slot.pillar),
    tone_variant: slot.tone_variant === 'custom' ? 'neutral_informational' : String(slot.tone_variant),
    message_body: String(slot.message_body).trim(), message_body_alt: String(slot.message_body_alt || ''),
    template_name: String(slot.template_name || 'health_plan_reminder'), status: 'active',
    start_date: String(body.start_date), end_date: String(body.end_date), created_at: prior.created_at || now, updated_at: now
  };
});
const inactive = existing.filter(row => !used.has(String(row.schedule_slot_id))).map(row => ({ ...row, status: 'inactive', updated_at: now }));
for (const nudge of plan.dated_nudges) {
  const match = String(nudge.nudge_id).match(/_(\d+)$/);
  const rule = active[match ? Number(match[1]) : -1];
  if (!rule) throw new Error(`could not map dated nudge ${nudge.nudge_id} to a weekly slot`);
  nudge.schedule_slot_id = rule.schedule_slot_id;
  nudge.nudge_id = `schd_${token(rule.schedule_slot_id)}_${String(nudge.scheduled_date).replace(/-/g, '')}`;
}
plan.schedule_rows = plan.dated_nudges.map(n => ({
  schedule_id: `sch_${n.nudge_id}`, nudge_id: n.nudge_id, user_id: n.user_id, status: 'approved', sent_at: '',
  wa_message_id: '', response_wa_id: '', barrier_followup_wa_id: '', tone_sent: '', response: '', responded_at: '',
  last_response_at: '', barrier_tag: '', done_count: 0, skip_count: 0, current_streak: 0, consecutive_skips: 0, last_updated: now
}));
plan.weekly_schedule_rows = active.concat(inactive);
plan.summary.weekly_schedule = active;
plan.summary.active_slot_count = active.length;
plan.summary.inactive_slot_count = inactive.length;
return [{ json: plan }];

// Re-approval replaces the active generated schedule instead of accumulating it.
// Remove time from generated IDs so message/time edits update the same logical
// source/date/occurrence row. Preserve prior rows for audit, but reject every
// older unsent generated row in the approval range so delivery cannot duplicate.
const plan = $json;
if (plan.decision !== 'approved') return [{ json: plan }];
const body = $('Webhook Approve').first().json.body || {};
const remapped = new Map();
for (const n of plan.dated_nudges) {
  const oldId = String(n.nudge_id);
  const stableId = oldId.replace(/_\d{4}_(\d+)$/, '_$1');
  remapped.set(oldId, stableId);
  n.nudge_id = stableId;
}
for (const s of plan.schedule_rows) {
  const oldNudgeId = String(s.nudge_id);
  s.nudge_id = remapped.get(oldNudgeId) || oldNudgeId;
  s.schedule_id = 'sch_' + s.nudge_id;
}
const desiredIds = new Set(plan.dated_nudges.map(n => String(n.nudge_id)));
const start = String(body.start_date || '');
const end = String(body.end_date || '');
const now = new Date().toISOString();
const stale = $('Read Existing Nudges for Approval').all().map(i => i.json).filter(n =>
  String(n.user_id) === String(plan.user_id) &&
  String(n.nudge_id || '').startsWith('schd_') &&
  String(n.status || '') === 'approved' &&
  String(n.scheduled_date || '') >= start && String(n.scheduled_date || '') <= end &&
  !desiredIds.has(String(n.nudge_id))
).map(n => ({ ...n, status: 'rejected', reviewed_at: now }));
plan.dated_nudges = plan.dated_nudges.concat(stale);
plan.schedule_rows = plan.schedule_rows.concat(stale.map(n => ({
  schedule_id: 'sch_' + n.nudge_id, nudge_id: n.nudge_id, user_id: n.user_id, status: 'rejected',
  sent_at: '', wa_message_id: '', barrier_followup_wa_id: '', tone_sent: '', response: '', responded_at: '',
  last_response_at: '', barrier_tag: '', done_count: 0, skip_count: 0, current_streak: 0,
  consecutive_skips: 0, last_updated: now
})));
plan.summary.superseded_count = stale.length;
return [{ json: plan }];

const plan = $json;
if (plan.decision !== 'approved') return [{ json: plan }];
const desiredIds = new Set(plan.dated_nudges.map(n => String(n.nudge_id)));
const today = new Date().toISOString().slice(0, 10);
const now = new Date().toISOString();
const alreadyIncluded = new Set(plan.dated_nudges.map(n => String(n.nudge_id)));
const stale = $('Read Existing Nudges for Approval').all().map(i => i.json).filter(n =>
  String(n.user_id) === String(plan.user_id) && String(n.nudge_id || '').startsWith('schd_') &&
  String(n.status || '') === 'approved' && String(n.scheduled_date || '') >= today &&
  !desiredIds.has(String(n.nudge_id)) && !alreadyIncluded.has(String(n.nudge_id))
).map(n => ({ ...n, status: 'rejected', reviewed_at: now }));
plan.dated_nudges = plan.dated_nudges.concat(stale);
plan.schedule_rows = plan.schedule_rows.concat(stale.map(n => ({
  schedule_id: 'sch_' + n.nudge_id, nudge_id: n.nudge_id, user_id: n.user_id, status: 'rejected',
  sent_at: '', wa_message_id: '', response_wa_id: '', barrier_followup_wa_id: '', tone_sent: '', response: '', responded_at: '',
  last_response_at: '', barrier_tag: '', done_count: 0, skip_count: 0, current_streak: 0, consecutive_skips: 0, last_updated: now
})));
plan.summary.cancelled_future_count = stale.length;
return [{ json: plan }];

const plan = $('Cancel Removed Future Slots').first().json;
const expected = plan.summary.weekly_schedule || [];
const actual = items.map(i => i.json).filter(r => String(r.user_id) === String(plan.user_id) && String(r.status) === 'active');
const fields = ['schedule_slot_id','user_id','source_nudge_id','prescription_id','day','scheduled_time','nudge_type','pillar','tone_variant','message_body','message_body_alt','template_name','status','start_date','end_date'];
const normalized = rows => rows.map(r => Object.fromEntries(fields.map(k => [k, String(r[k] == null ? '' : r[k])]))).sort((a, b) => a.schedule_slot_id.localeCompare(b.schedule_slot_id));
if (JSON.stringify(normalized(actual)) !== JSON.stringify(normalized(expected))) throw new Error('weekly_schedule persistence verification failed');
return [{ json: { ...plan.summary, persisted: true, weekly_schedule: actual } }];

const expected = String($env.N8N_PROXY_SECRET || '');
const supplied = String(($json.headers || {})['x-n8n-proxy-secret'] || '');
const body = $json.body || {};
return [{ json: { user_id: String(body.user_id || '').trim(), doctor_id: String(body.doctor_id || '').trim(), proxy_authorized: Boolean(expected && supplied === expected) } }];

const expected = String($env.N8N_PROXY_SECRET || '');
const supplied = String(($json.headers || {})['x-n8n-proxy-secret'] || '');
const body = $json.body || {};
return [{ json: { user_id: String(body.user_id || '').trim(), name: String(body.name || '').trim(), phone: String(body.phone || '').trim(), email: String(body.email || '').trim(), user_status: String(body.user_status || '').trim(), proxy_authorized: Boolean(expected && supplied === expected) } }];

const expected = $('Authorize Patient Update').first().json;
const matches = items.map(i => i.json).filter(row => String(row.user_id || '') === expected.user_id);
const fields = ['user_id', 'name', 'phone', 'email', 'user_status'];
const patient = matches.length === 1 ? matches[0] : null;
const persisted = Boolean(patient && fields.every(key => String(patient[key] == null ? '' : patient[key]) === String(expected[key] == null ? '' : expected[key])));
return [{ json: persisted
  ? { status: 'ok', persisted: true, patient: Object.fromEntries(fields.map(key => [key, patient[key]])) }
  : { status: 'persistence_conflict', persisted: false, patient: null, error: 'Patient update was not confirmed in Google Sheets.' }
}];
